    private static func parseRanges(_ s: String) -> [(UInt32, UInt32)] {
        var out: [(UInt32, UInt32)] = []
        out.reserveCapacity(1024)
        for item in s.split(separator: ",") {
            let parts = item.split(separator: "-")
            out.append((UInt32(parts[0], radix: 16)!, UInt32(parts[1], radix: 16)!))
        }
        return out
    }

    private static let drop: [(UInt32, UInt32)] = parseRanges(dropData)
    private static let letter: [(UInt32, UInt32)] = parseRanges(letterData)

    private struct FoldTable {
        var keys: [UInt32] = []
        var offsets: [Int] = []   // 長度 keys.count + 1
        var pool: [UInt32] = []
    }

    private static let fold: FoldTable = {
        var t = FoldTable()
        for entry in foldData.split(separator: ";", omittingEmptySubsequences: false) {
            guard let eq = entry.firstIndex(of: "=") else { continue }
            t.keys.append(UInt32(entry[entry.startIndex..<eq], radix: 16)!)
            t.offsets.append(t.pool.count)
            let value = entry[entry.index(after: eq)...]
            for h in value.split(separator: " ") {
                t.pool.append(UInt32(h, radix: 16)!)
            }
        }
        t.offsets.append(t.pool.count)
        return t
    }()

    private static func inRanges(_ r: [(UInt32, UInt32)], _ cp: UInt32) -> Bool {
        var lo = 0
        var hi = r.count - 1
        while lo <= hi {
            let mid = (lo + hi) / 2
            if cp < r[mid].0 {
                hi = mid - 1
            } else if cp > r[mid].1 {
                lo = mid + 1
            } else {
                return true
            }
        }
        return false
    }

    public static func isDrop(_ cp: UInt32) -> Bool { return inRanges(drop, cp) }
    public static func isLetter(_ cp: UInt32) -> Bool { return inRanges(letter, cp) }
    public static func isCjk(_ cp: UInt32) -> Bool {
        for r in cjkRanges where r.contains(cp) { return true }
        return false
    }

    /// SPEC §2 步驟 1–6。一律以 unicodeScalars 迭代（不可用 Character / 字素叢集）。
    public static func foldScalar(_ cp: UInt32, into out: inout [UInt32]) {
        if isDrop(cp) { return }
        let keys = fold.keys
        var lo = 0
        var hi = keys.count - 1
        while lo <= hi {
            let mid = (lo + hi) / 2
            if keys[mid] < cp {
                lo = mid + 1
            } else if keys[mid] > cp {
                hi = mid - 1
            } else {
                out.append(contentsOf: fold.pool[fold.offsets[mid]..<fold.offsets[mid + 1]])
                return
            }
        }
        out.append(cp)
    }

    public static let maxInputScalars = 16384

    /// 最多處理前 maxInputScalars 個 scalar（Swift 的 String 會把落單代理字元換成 U+FFFD，它在 DROP 裡）。
    /// fold 之後一律用 [UInt32] 比較、搜尋、計數、排序；禁止用 String / Character / Foundation 的字串 API
    /// （它們用標準等價或字素叢集語意，會與其他平台不同）。
    public static func fold(_ s: String) -> [UInt32] {
        var out: [UInt32] = []
        out.reserveCapacity(s.unicodeScalars.count)
        var count = 0
        for u in s.unicodeScalars {
            if count == maxInputScalars { break }
            count += 1
            foldScalar(u.value, into: &out)
        }
        composeHangul(&out)
        return out
    }

    /// 韓文字母組合（L+V→LV、LV+T→LVT），讓 fold 的輸出對韓文也是 NFC 形式。
    public static func composeHangul(_ s: inout [UInt32]) {
        var w = 0
        for r in 0..<s.count {
            let c = s[r]
            if w > 0 {
                let last = s[w - 1]
                if last >= 0x1100 && last <= 0x1112 && c >= 0x1161 && c <= 0x1175 {
                    s[w - 1] = 0xAC00 + ((last - 0x1100) * 21 + (c - 0x1161)) * 28
                    continue
                }
                if last >= 0xAC00 && last <= 0xD7A3 && (last - 0xAC00) % 28 == 0 && c >= 0x11A8 && c <= 0x11C2 {
                    s[w - 1] = last + (c - 0x11A7)
                    continue
                }
            }
            s[w] = c
            w += 1
        }
        s.removeLast(s.count - w)
    }

    /// SPEC §2 步驟 9：只留字母，每段連續 ASCII 數字換成一個 "#"。
    public static func textForm(_ f: [UInt32]) -> [UInt32] {
        var out: [UInt32] = []
        var inDigits = false
        for cp in f {
            if cp >= 0x30 && cp <= 0x39 {
                if !inDigits { out.append(0x23) }
                inDigits = true
            } else {
                inDigits = false
                if isLetter(cp) { out.append(cp) }
            }
        }
        return out
    }

    public static func cjkForm(_ t: [UInt32]) -> [UInt32] {
        return t.filter { isCjk($0) }
    }

    public static func wlen(_ t: [UInt32]) -> Int {
        var w = 0
        for cp in t { w += isCjk(cp) ? 2 : 1 }
        return w
    }

    public static func string(_ scalars: [UInt32]) -> String {
        var s = String.UnicodeScalarView()
        for cp in scalars {
            if let u = Unicode.Scalar(cp) { s.append(u) }
        }
        return String(s)
    }

    // ---- SipHash-2-4：Swift 的 + * 溢位會中止程式，一律用 &+ &* 與 rotl ----
    @inline(__always) private static func rotl(_ x: UInt64, _ b: UInt64) -> UInt64 {
        return (x << b) | (x >> (64 &- b))
    }

    public static func sipHash24(k0: UInt64, k1: UInt64, _ m: [UInt8]) -> UInt64 {
        var v0: UInt64 = 0x736f6d6570736575 ^ k0
        var v1: UInt64 = 0x646f72616e646f6d ^ k1
        var v2: UInt64 = 0x6c7967656e657261 ^ k0
        var v3: UInt64 = 0x7465646279746573 ^ k1
        func round() {
            v0 = v0 &+ v1; v1 = rotl(v1, 13); v1 ^= v0; v0 = rotl(v0, 32)
            v2 = v2 &+ v3; v3 = rotl(v3, 16); v3 ^= v2
            v0 = v0 &+ v3; v3 = rotl(v3, 21); v3 ^= v0
            v2 = v2 &+ v1; v1 = rotl(v1, 17); v1 ^= v2; v2 = rotl(v2, 32)
        }
        let len = m.count
        let end = len - (len % 8)
        var i = 0
        while i < end {
            var mi: UInt64 = 0
            for j in stride(from: 7, through: 0, by: -1) { mi = (mi << 8) | UInt64(m[i + j]) }
            v3 ^= mi
            round(); round()
            v0 ^= mi
            i += 8
        }
        var b: UInt64 = UInt64(len & 0xff) << 56
        var j = end
        while j < len {
            b |= UInt64(m[j]) << UInt64(8 * (j - end))
            j += 1
        }
        v3 ^= b
        round(); round()
        v0 ^= b
        v2 ^= 0xff
        round(); round(); round(); round()
        return v0 ^ v1 ^ v2 ^ v3
    }

    /// key16：k0 = key[0..<8] 小端，k1 = key[8..<16] 小端；訊息 = UTF-8(tag) 0x1F payload
    public static func keyedHashBytes(key16: [UInt8], tag: String, payload: [UInt8]) -> UInt64 {
        var k0: UInt64 = 0
        var k1: UInt64 = 0
        for j in stride(from: 7, through: 0, by: -1) { k0 = (k0 << 8) | UInt64(key16[j]) }
        for j in stride(from: 15, through: 8, by: -1) { k1 = (k1 << 8) | UInt64(key16[j]) }
        var m = Array(tag.utf8)
        m.append(0x1f)
        m.append(contentsOf: payload)
        return sipHash24(k0: k0, k1: k1, m)
    }

    /// H(tag, payload)：payload 以 UTF-8 編碼。
    public static func keyedHash(key16: [UInt8], tag: String, payload: String) -> UInt64 {
        return keyedHashBytes(key16: key16, tag: tag, payload: Array(payload.utf8))
    }

    public static func hex64(_ v: UInt64) -> String {
        let s = String(v, radix: 16)
        return String(repeating: "0", count: 16 - s.count) + s
    }

}
